-- Seed 0014 (Phase 8): the audit check catalogue and the cash limits of the Income-tax Act (rule table, law is data).
-- System data only. Idempotent (ON CONFLICT DO NOTHING). No value here is 'verified': see docs/PHASE8_LEGAL_VALUES.md.
-- Statuses: secondary_verified = read on a secondary page in the planning step; pending = recalled / not verified from an official text.

INSERT INTO audit_rule_limits (rule_key, law, section_ref, amount, breach_when, disallow_percent, effective_from, effective_to,
                               source_reference, verification_status, notes)
VALUES
    ('cash_payment_daily_limit', 'it_act_1961', 'section 40A(3) (and Rule 6DD for the exceptions)', 10000.00, 'above', 100.00,
     DATE '2017-04-01', DATE '2026-03-31',
     'Income-tax Act 1961 s.40A(3) as recalled; official text not read in planning step 8.0', 'pending',
     'Per person per day, aggregate of payments otherwise than by account payee cheque / draft / electronic mode. Rule 6DD exceptions are decided by the reviewer, never by the engine.'),
    ('cash_payment_daily_limit', 'it_act_2025', 'successor of s.40A(3): section number NOT verified', 10000.00, 'above', 100.00,
     DATE '2026-04-01', NULL,
     'Income-tax Act 2025 (in force 1 April 2026): section number and any change of limit not read; carried over from 1961 Act as recalled', 'pending',
     'The page taxclue.in/blog/section-269ss-269st-income-tax-act-2025-mapping does not mention 40A(3); the owner / CA must confirm the section and limit.'),
    ('cash_payment_daily_limit_transport', 'it_act_1961', 'section 40A(3A) / Rule 6DD(g) (goods carriage hire)', 35000.00, 'above', 100.00,
     DATE '2017-04-01', DATE '2026-03-31',
     'Income-tax Act 1961 s.40A(3) read with Rule 6DD(g) as recalled; official text not read', 'pending',
     'Higher limit for payments to a transporter for plying, hiring or leasing goods carriages. Applies only to ledgers the accountant marks as transporters.'),
    ('cash_payment_daily_limit_transport', 'it_act_2025', 'successor of Rule 6DD(g): NOT verified', 35000.00, 'above', 100.00,
     DATE '2026-04-01', NULL,
     'Income-tax Rules 2026 / Act 2025: not read; carried over as recalled', 'pending', NULL),
    ('cash_receipt_limit', 'it_act_1961', 'section 269ST', 200000.00, 'at_or_above', NULL,
     DATE '2017-04-01', DATE '2026-03-31',
     'Income-tax Act 1961 s.269ST; "two lakh rupees or more" quoted on taxclue.in (secondary page); official text not read', 'secondary_verified',
     'Receipt of the limit or more: in aggregate from one person in a day, or in respect of one transaction, or transactions of one event. The check can test per person per day and per voucher; "one event" is a reviewer judgement.'),
    ('cash_receipt_limit', 'it_act_2025', 'section 186 (replaces s.269ST per taxclue.in mapping)', 200000.00, 'at_or_above', NULL,
     DATE '2026-04-01', NULL,
     'Income-tax Act 2025 s.186 (section mapping on taxclue.in, secondary page); the limit is carried over, section text not read', 'pending',
     'Penalty for breach sits in section 451 (replaces 271DA) per the same page; not used by the engine.')
ON CONFLICT (rule_key, law, effective_from) DO NOTHING;

INSERT INTO audit_checks (check_id, title, description, rule_text, severity, category, evidence_query, rule_key, sort_order)
VALUES
    ('A-01', 'Duplicate bills', 'Two or more live vouchers carry the same party and the same supplier bill / reference number (purchase, debit note, payment).',
     'Same party ledger + normalised reference no (case and spaces ignored) on more than one non-draft, non-reversed voucher; a reversed voucher and its reversal are ignored.',
     'warning', 'books', 'ev_duplicate_bills: vouchers by (party_ledger_id, reference_no) having count > 1', NULL, 10),
    ('A-02', 'Duplicate payments', 'The same party was paid the same amount more than once within a few days.',
     'Same party ledger + same bank/cash payment total within N days (parameter, default 7) on live Payment vouchers, or the same payment reference no.',
     'warning', 'books', 'ev_duplicate_payments: payment vouchers by (party_ledger_id, total) within the window', NULL, 20),
    ('A-03', 'Missing supporting document', 'A posted voucher of a type that needs a bill has no document linked (Phase 7 document_vouchers).',
     'Purchase, Payment and Debit Note vouchers (parameter: types and minimum amount, default every amount) must have at least one link in document_vouchers; Journal and Contra are not tested.',
     'warning', 'books', 'ev_missing_documents: vouchers with no document_vouchers row', NULL, 30),
    ('A-04', 'Voucher number gap', 'The posted numbers of a type in a year are not continuous.',
     'Per client + financial year + voucher type, the numeric parts of posted / reversed voucher numbers must run 1..N without a gap; the sequence counter must equal N.',
     'error', 'books', 'ev_number_gaps: voucher_number_sequences vs posted numbers', NULL, 40),
    ('A-05', 'Cash payment above the daily limit', 'Cash payments to one person on one day exceed the Income-tax limit: expenditure may be disallowed.',
     'Sum of Payment vouchers paid from Cash-in-hand to one party (or one expense ledger when no party) on one date; flag when the sum is above audit_rule_limits cash_payment_daily_limit for that date (transport limit for ledgers marked transporter). Disallowance = the whole day amount x disallow_percent. Rule 6DD exceptions are reviewer decisions.',
     'error', 'books', 'ev_cash_payments: cash payment lines grouped by (counter ledger, voucher_date)', 'cash_payment_daily_limit', 50),
    ('A-06', 'Cash receipt above the legal limit', 'Cash received from one person in a day (or in one voucher) reaches the legal limit.',
     'Sum of Receipt / Sales vouchers settled in cash from one party on one date, and each single voucher; flag when at or above audit_rule_limits cash_receipt_limit for that date.',
     'error', 'books', 'ev_cash_receipts: cash receipt lines grouped by (party, voucher_date)', 'cash_receipt_limit', 60),
    ('A-07', 'MSME dues past the legal days', 'A micro or small enterprise supplier is unpaid beyond the legal payment days at year end (or was paid late).',
     'Reuse Phase 2 engine/msme.flag_msme_overdue with the msme_payment_rules rows of the date: days with / without written agreement per category.',
     'error', 'compliance', 'ev_msme: open bills of MSME parties with due date and days overdue', NULL, 70),
    ('A-08', 'GST books versus returns', 'GST in the books differs from the filed GSTR-1 / GSTR-3B or from GSTR-2B.',
     'Reuse Phase 3 engine/gst_tieout.build_tieout for the period; any non-zero difference is a finding with the tie-out cause.',
     'error', 'compliance', 'ev_gst_tieout: gst_filed_returns vs books workings per period', NULL, 80),
    ('A-09', 'TDS not deducted', 'A payment to a party crossed the TDS threshold of its section but no tax was deducted.',
     'Reuse Phase 4 engine/tds_calc on posted vouchers of the year: tax due by section / rate / threshold on the voucher date versus tax recorded in tds_voucher_items.',
     'error', 'compliance', 'ev_tds_missing: vouchers where computed tax > 0 and no deduction item', NULL, 90),
    ('A-10', 'TDS short deducted', 'Tax deducted is less than the tax due.',
     'Same computation as A-09; deducted amount below computed amount (lower-deduction certificate honoured when present).',
     'error', 'compliance', 'ev_tds_short: deduction items with deducted < computed', NULL, 100),
    ('A-11', 'TDS late deposited', 'TDS was deposited after the due date, or not deposited.',
     'Reuse Phase 4 engine/tds_challan with tds_due_dates / tds_interest_rules: challan date later than the due date of the deduction month, or no challan allocation.',
     'error', 'compliance', 'ev_tds_late: deduction items with challan allocation date > due date', NULL, 110),
    ('A-12', 'Round-amount entries', 'Vouchers whose total is an exact round number (multiple of 1,000 by default) in unusual numbers.',
     'Voucher total divisible by the round unit (parameter, default 1000.00) and at least the minimum amount (parameter, default 10000.00); listed for review, never a conclusion.',
     'info', 'books', 'ev_round_amounts: posted vouchers whose total mod unit = 0', NULL, 120),
    ('A-13', 'Entries on Sundays and holidays', 'Vouchers dated on a Sunday or on a holiday of the client calendar.',
     'voucher_date falls on a Sunday (calendar) or in audit_holidays for the client; sales and receipts of a business open on that day are reviewer decisions.',
     'info', 'books', 'ev_holiday_entries: vouchers by voucher_date weekday / audit_holidays', NULL, 130),
    ('A-14', 'Entries after the period was locked', 'A voucher was posted after the lock of its period, or long after its date.',
     'From audit_log (lock / unlock actions) and vouchers.posted_at: a voucher dated in a period that was locked before posted_at (lock, unlock, post), or posted more than N days after the period end (parameter, default 30).',
     'warning', 'books', 'ev_late_entries: vouchers with posted_at vs periods lock events in audit_log', NULL, 140),
    ('A-15', 'Unusual ledger movement', 'A ledger moved much more or less than in the previous year.',
     'Per ledger, absolute change of the year total against the previous year >= the minimum amount (parameter) and ratio outside the band (parameter, default +50% / -50%); previous year zero is reported as new.',
     'review', 'analytical', 'ev_variance: ledger totals this year vs last year', NULL, 150),
    ('A-16', 'Negative cash history', 'The cash book was negative at the end of some day.',
     'Reuse Phase 2 engine/cash_rules (C-01 logic) over all posted vouchers of the year: any day with a negative closing cash balance.',
     'error', 'compliance', 'ev_negative_cash: cash ledger day-end balances < 0', NULL, 160),
    ('A-17', 'Negative stock history', 'An item had a negative stock quantity on some date.',
     'Reuse Phase 5 inventory movements and valuation: running quantity of an item / godown below zero on any date.',
     'error', 'compliance', 'ev_negative_stock: stock_movements running quantity < 0', NULL, 170),
    ('A-18', 'Related-party transactions', 'Postings with parties the accountant flagged as related.',
     'Every posted voucher line on a ledger flagged in audit_related_parties (active) in the period; totals per party; listed for disclosure and fair-value review (no conclusion).',
     'info', 'books', 'ev_related_party: voucher_lines on flagged ledgers', NULL, 180)
ON CONFLICT (check_id) DO NOTHING;
